import json
for f in ['reasoning','coding','cowork']:
    d = json.load(open(f'/workspace/submission/data/{f}.json'))
    items = d.get('questions', d) if isinstance(d, dict) else d
    if isinstance(d, dict) and 'questions' in d:
        items = d['questions']
    mt = [q.get('max_tokens') for q in items]
    kinds = {}
    for q in items:
        kinds[q.get('type')] = kinds.get(q.get('type'),0)+1
    print(f, 'n=',len(items), 'kinds=',kinds, 'max_tokens histogram=', sorted(set(mt), key=lambda x:(x is None, x)))
"",
  "description": "Inspect data files for max_tokens and types"
}

